#include <iostream>
using namespace std;
int main(){const int M=20;int a[M][M],r,c,ch;cout<<"Rows columns: ";if(!(cin>>r>>c)||r<1||r>M||c<1||c>M)return 1;for(int i=0;i<r;i++)for(int j=0;j<c;j++)if(!(cin>>a[i][j]))return 1;do{cout<<"\n1.Display 2.Transpose 3.Row sums 4.Column sums 0.Exit\n";if(!(cin>>ch))return 1;if(ch==1){for(int i=0;i<r;i++){for(int j=0;j<c;j++)cout<<a[i][j]<<"\t";cout<<"\n";}}else if(ch==2){for(int j=0;j<c;j++){for(int i=0;i<r;i++)cout<<a[i][j]<<"\t";cout<<"\n";}}else if(ch==3){for(int i=0;i<r;i++){int s=0;for(int j=0;j<c;j++)s+=a[i][j];cout<<s<<"\n";}}else if(ch==4){for(int j=0;j<c;j++){int s=0;for(int i=0;i<r;i++)s+=a[i][j];cout<<s<<"\n";}}}while(ch!=0);return 0;}